private static function makeTimezone(mixed $value): ?DateTimeZone
{
    if ($value instanceof DateTimeZone) {
        return $value;
    }

    if (!\is_string($value) || !preg_match('/[a-z]|[+-]\d{1,2}:\d{2}/i', $value)) {
        return null;
    }

    try {
        return CarbonTimeZone::instance($value);
    } catch (Throwable) {
        return null;
    }
}

